CREATE OR REPLACE FUNCTION public.can_manage_fitness(_team text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.team_members WHERE user_id=auth.uid() AND public.canonical_team_slug(team_slug)=public.canonical_team_slug(_team) AND lower(role)='coach') OR (public.has_role(auth.uid(),'coach') AND EXISTS(SELECT 1 FROM public.user_age_groups WHERE user_id=auth.uid() AND public.canonical_team_slug(age_group)=public.canonical_team_slug(_team)))); $$;
REVOKE ALL ON FUNCTION public.can_manage_fitness(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_manage_fitness(text) TO authenticated;
CREATE TABLE public.fitness_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_slug text NOT NULL, created_by uuid NOT NULL DEFAULT auth.uid(), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','completed')), protocol text NOT NULL DEFAULT '20m-8.5-v1' CHECK(protocol='20m-8.5-v1'));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fitness_sessions TO authenticated;
GRANT ALL ON public.fitness_sessions TO service_role;
ALTER TABLE public.fitness_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY fitness_sessions_read ON public.fitness_sessions FOR SELECT TO authenticated USING(public.can_manage_fitness(team_slug) OR public.is_team_member(auth.uid(),team_slug));
CREATE POLICY fitness_sessions_write ON public.fitness_sessions FOR ALL TO authenticated USING(public.can_manage_fitness(team_slug)) WITH CHECK(public.can_manage_fitness(team_slug));
CREATE TABLE public.fitness_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.fitness_sessions(id) ON DELETE CASCADE, player_id uuid NOT NULL REFERENCES public.player_registrations(id) ON DELETE CASCADE, completed_shuttles integer NOT NULL CHECK(completed_shuttles BETWEEN 0 AND 247), recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,player_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fitness_results TO authenticated;
GRANT ALL ON public.fitness_results TO service_role;
ALTER TABLE public.fitness_results ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.can_view_fitness_player(_player uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.player_registrations p WHERE p.id=_player AND (p.user_id=auth.uid() OR public.can_manage_fitness(p.preferred_age_group) OR EXISTS(SELECT 1 FROM public.guardians g WHERE g.parent_user_id=auth.uid() AND g.status IN ('active','approved','linked') AND public.canonical_team_slug(g.team_slug)=public.canonical_team_slug(p.preferred_age_group) AND lower(trim(g.player_name))=lower(trim(p.child_name))))); $$;
REVOKE ALL ON FUNCTION public.can_view_fitness_player(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_view_fitness_player(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_write_fitness_result(_session uuid,_player uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.fitness_sessions s JOIN public.player_registrations p ON p.id=_player WHERE s.id=_session AND public.canonical_team_slug(p.preferred_age_group)=public.canonical_team_slug(s.team_slug) AND public.can_manage_fitness(s.team_slug)); $$;
REVOKE ALL ON FUNCTION public.can_write_fitness_result(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_write_fitness_result(uuid,uuid) TO authenticated;
CREATE POLICY fitness_results_read ON public.fitness_results FOR SELECT TO authenticated USING(public.can_view_fitness_player(player_id));
CREATE POLICY fitness_results_write ON public.fitness_results FOR ALL TO authenticated USING(public.can_write_fitness_result(session_id,player_id)) WITH CHECK(public.can_write_fitness_result(session_id,player_id));
CREATE OR REPLACE FUNCTION public.get_fitness_roster(_team text) RETURNS TABLE(id uuid,child_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.child_name FROM public.player_registrations p WHERE public.canonical_team_slug(p.preferred_age_group)=public.canonical_team_slug(_team) AND public.can_view_fitness_player(p.id) ORDER BY p.child_name; $$;
REVOKE ALL ON FUNCTION public.get_fitness_roster(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_fitness_roster(text) TO authenticated;
CREATE INDEX fitness_sessions_team_date ON public.fitness_sessions(team_slug,started_at DESC);
CREATE INDEX fitness_results_player ON public.fitness_results(player_id,session_id);